select energy_manager.load_cards($cards$[
{"id":"p4-b03-035","paper":4,"topic":"Cement Waste Heat Recovery","kind":"problem","front":"Cement case study: preheater exit gas is 167,559 Nm³/h, with Cp 0.355 kcal/kg°C, cooled from 295 °C to 195 °C. At 20% conversion efficiency, what power can be generated?","back":"About 1.383 MW.","explain":"Recoverable heat is gas flow × Cp × temperature drop. The book's calculation line prints Cp as 0.316, but its result of 5.948 million kcal/h only follows from 0.355, so 0.355 is used here.","flash":false,"source":"BEE Book 4 Ch 03 p77","steps":[{"prompt":"Find the heat recoverable from the preheater gas.","answer":"167,559 × 0.355 × (295 − 195) = 5.948 million kcal/h","explain":"Gas flow times Cp times temperature drop."},{"prompt":"Find the useful heat at 20% conversion.","answer":"5.948 × 0.20 = 1.1896 million kcal/h","explain":"Only 20% of the recoverable heat becomes power in this circuit."},{"prompt":"Convert to MW.","answer":"1.1896 × 10⁶ ÷ 860 = 1,383 kW = 1.383 MW","explain":"860 kcal = 1 kWh."}],"order":4194},
{"id":"p4-b03-036","paper":4,"topic":"Cement Waste Heat Recovery","kind":"problem","front":"Same cement case study: clinker cooler exit gas is 91,000 Nm³/h, Cp 0.316 kcal/kg°C, cooled from 360 °C to 130 °C. At 21% conversion efficiency, what is the cooler power, and the total with the preheater section?","back":"Cooler section about 1.615 MW. Total with the preheater section (1.383 MW) about 3.0 MW.","explain":"Each gas stream is worked out separately with its own conversion efficiency, then the two are added. The total is the waste heat power potential under the book's assumptions.","flash":false,"source":"BEE Book 4 Ch 03 p77","steps":[{"prompt":"Find the heat recoverable from the cooler gas.","answer":"91,000 × 0.316 × (360 − 130) = 6.613 million kcal/h","explain":"Gas flow times Cp times temperature drop."},{"prompt":"Find the useful heat at 21% conversion.","answer":"6.613 × 0.21 = 1.389 million kcal/h","explain":"Only 21% of the recoverable heat becomes power in this circuit."},{"prompt":"Convert to MW.","answer":"1.389 × 10⁶ ÷ 860 = 1,615 kW = 1.615 MW","explain":"860 kcal = 1 kWh."},{"prompt":"Add the two sections.","answer":"1.383 + 1.615 = 2.998, about 3.0 MW","explain":"Total waste heat power potential for the plant."}],"order":4195},
{"id":"p4-b03-037","paper":4,"topic":"Solved Examples","kind":"problem","front":"A boiler in a textile and paper cogeneration plant makes 60 TPH of steam at 810 kcal/kg from 80 °C feed water (enthalpy taken as 80 kcal/kg), at 80% efficiency. Coal GCV is 5000 kcal/kg. How much coal is burnt per hour?","back":"About 10.95 t/h (about 263 t per day at 24 hours).","explain":"Boiler efficiency fixes the fuel needed: steam heat gain divided by fuel heat input. The per-day figure assumes 24 hours of operation.","flash":false,"source":"BEE Book 4 Ch 03 p78","steps":[{"prompt":"Find the heat gained by the steam per hour.","answer":"60,000 × (810 − 80) = 43.8 million kcal/h","explain":"Steam output times enthalpy rise from feed water."},{"prompt":"Set up the coal balance.","answer":"Coal × 5000 × 0.80 = 43.8 million kcal/h","explain":"Efficiency converts coal heat into steam heat."},{"prompt":"Solve for coal per hour.","answer":"43,800,000 ÷ 4000 = 10,950 kg/h = 10.95 t/h","explain":"Coal flow is heat gain divided by heat per kg of coal at efficiency."},{"prompt":"Convert to a daily figure.","answer":"10.95 × 24 ≈ 263 t/day","explain":"Multiply by operating hours."}],"order":4196},
{"id":"p4-b03-038","paper":4,"topic":"Solved Examples","kind":"problem","front":"Same plant: the turbine takes in 60 TPH at 810 kcal/kg and exhausts 60 TPH at 660 kcal/kg to process. Turbine, alternator and other losses are 8%, and auxiliary consumption is 10%. What are the gross and net power outputs per hour?","back":"Gross about 9,628 kWh/h; net about 8,665 kWh/h after 10% auxiliary consumption.","explain":"The enthalpy drop is reduced by 8% losses before conversion to kWh (divided by 860). Auxiliary consumption then takes 10% of gross output. The book's gross line has a stray ×10%, which is a typo.","flash":false,"source":"BEE Book 4 Ch 03 p79","steps":[{"prompt":"Find the heat in and out.","answer":"60,000 × 810 = 48.6 million kcal/h in; 60,000 × 660 = 39.6 million kcal/h out","explain":"Steam flow times enthalpy at each point."},{"prompt":"Find the heat drop.","answer":"48.6 − 39.6 = 9 million kcal/h","explain":"Heat converted in the turbine."},{"prompt":"Remove the 8% losses.","answer":"9 × 0.08 = 0.72; useful heat = 8.28 million kcal/h","explain":"Losses are taken off the heat drop."},{"prompt":"Convert to gross power.","answer":"8.28 million ÷ 860 = 9,628 kWh/h","explain":"Gross generation in kWh per hour."},{"prompt":"Take off auxiliary power.","answer":"9,628 × 0.10 = 962.8; net = 8,665.2 kWh/h","explain":"Net power is gross power minus auxiliary consumption."}],"order":4197},
{"id":"p4-b03-039","paper":4,"topic":"Solved Examples","kind":"problem","front":"Same plant: 40 TPH of steam goes to the paper plant at 5 t of steam per t of paper, and the paper plant uses 600 kWh per t. Net generation is 8,665.2 kWh/h. How much power goes to the textile plant per hour?","back":"About 3,865 kWh/h.","explain":"Paper output comes from steam flow divided by specific steam consumption. Its power draw comes off the net generation, and the remainder goes to the textile plant.","flash":false,"source":"BEE Book 4 Ch 03 p79","steps":[{"prompt":"Find the paper output.","answer":"40 ÷ 5 = 8 t/h","explain":"Steam flow divided by steam per tonne of paper."},{"prompt":"Find the paper plant's power.","answer":"8 × 600 = 4,800 kWh/h","explain":"Specific power consumption times output."},{"prompt":"Find the textile plant's power.","answer":"8,665.2 − 4,800 = 3,865.2 kWh/h","explain":"Net generation minus the paper plant's use."}],"order":4198},
{"id":"p4-b03-040","paper":4,"topic":"Solved Examples","kind":"problem","front":"Same plant: the turbine heat drop is 9 million kcal/h and gross generation is 9,628 kWh/h. What is the gross heat rate of the turbine?","back":"About 935 kcal/kWh (book prints 934.7).","explain":"Gross heat rate uses the turbine's enthalpy drop over gross generation, not the net output. A lower value means less heat used per kWh.","flash":false,"source":"BEE Book 4 Ch 03 p79","steps":[{"prompt":"Identify the heat input to the turbine.","answer":"9 million kcal/h (48.6 − 39.6)","explain":"Heat drop in the turbine."},{"prompt":"Identify the gross generation.","answer":"9,628 kWh/h","explain":"From the gross power calculation."},{"prompt":"Divide heat by generation.","answer":"9,000,000 ÷ 9,628 ≈ 934.8 kcal/kWh (book prints 934.7)","explain":"The book's line for this is garbled in the OCR, but the ratio gives the same figure."}],"order":4199},
{"id":"p4-b04-001","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"Why should heat exchanger performance be assessed periodically?","back":"Performance falls with time, off-design operation, fouling, scaling and corrosion, so it must be checked to keep the exchanger efficient.","explain":"Any deviation from the design figures indicates fouling. Regular checks let cleaning and maintenance be planned instead of reacting to failures.","flash":true,"source":"BEE Book 4 Ch 04 p85","order":4200},
{"id":"p4-b04-002","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"What does a heat exchanger performance assessment aim to determine?","back":"Heat exchanger duty, overall heat transfer coefficient, effectiveness, and the process and utility side pressure drops.","explain":"These results are compared with design values. A deviation from design is the warning sign of fouling.","flash":false,"source":"BEE Book 4 Ch 04 p85","order":4201},
{"id":"p4-b04-003","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"What does a small overall heat transfer coefficient U mean?","back":"Heat moves across the exchanger with more difficulty. A smaller U means harder heat transfer.","explain":"U is defined by Q = U × A × LMTD. For a given duty, fouling adds resistance and pulls U down, which is why the chapter uses U as the main fouling indicator.","flash":true,"source":"BEE Book 4 Ch 04 p85","order":4202},
{"id":"p4-b04-004","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"In what units is the overall heat transfer coefficient U given in the chapter?","back":"kcal/hr/m²/°C in the definition, and kW/m²·K in the worked examples.","explain":"1 kW = 860 kcal/h, so the two forms differ by that factor. Keep the units the same when comparing a test U with the design U.","flash":false,"source":"BEE Book 4 Ch 04 p85","order":4203},
{"id":"p4-b04-005","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"Why is a drop in heat duty not a conclusive sign of fouling?","back":"Duty can fall because of process changes, heat losses or lower hot or cold flow rates. U is the more reliable fouling indicator.","explain":"Duty is a useful first check but it can mislead. The chapter therefore determines U in the field as the basis of the performance assessment.","flash":false,"source":"BEE Book 4 Ch 04 p87","order":4204},
{"id":"p4-b04-006","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"What is the heat duty formula for the hot fluid?","back":"Q = W × Cp × (Thi − Tho), where W is the hot fluid flow and Cp its specific heat.","explain":"The cold side gives the same duty when the balance closes: Q = w × Cp × (Tco − Tci). A gap between hot and cold duties points to heat loss or an instrument error.","flash":false,"source":"BEE Book 4 Ch 04 p87","order":4205},
{"id":"p4-b04-007","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"What are the sensible and latent parts of heat duty, and how are they calculated?","back":"Q = qs + qL. Sensible: qs = W × Cp × ΔT ÷ 3600 kW. Latent: qL = W × λ ÷ 3600 kW, with λ the latent heat in kJ/kg.","explain":"Condensing vapour gives mostly latent heat, so the latent term carries most of the duty. Dividing by 3600 converts kg/h and kJ/kg to kW.","flash":false,"source":"BEE Book 4 Ch 04 p89","order":4206},
{"id":"p4-b04-008","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"Name the four common types of fouling.","back":"Chemical, biological, deposition and corrosion fouling.","explain":"Fouling is a layer of dirt or other deposit on the tube surfaces. It adds resistance to heat flow, so it reduces effectiveness.","flash":false,"source":"BEE Book 4 Ch 04 p87","order":4207},
{"id":"p4-b04-009","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"Why can overstated fouling factors be a problem?","back":"Badly chosen fouling factors can increase cleaning frequency, which cancels the benefit of careful design.","explain":"End users often overstate fouling factors to cut the number of cleanings. The fouling factors are normally set by the client from plant experience.","flash":false,"source":"BEE Book 4 Ch 04 p87","order":4208},
{"id":"p4-b04-010","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"What happens to effectiveness as the fouling factor rises?","back":"Effectiveness drops.","explain":"Fouling adds thermal resistance, so less heat moves between the streams for the same inlet conditions.","flash":false,"source":"BEE Book 4 Ch 04 p87","order":4209},
{"id":"p4-b04-011","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"What is the LMTD correction factor F used for?","back":"It corrects the LMTD where the flow is not true counter-current, such as multi-pass shell-and-tube or cross flow. Corrected LMTD = F × LMTD.","explain":"Multi-pass flow mixes co-current and counter-current paths, so the plain logarithmic mean is not exact. F is a function of the two ratios R and P and the number of shell passes.","flash":false,"source":"BEE Book 4 Ch 04 p86","order":4210},
{"id":"p4-b04-012","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"How are the LMTD correction ratios R and P defined?","back":"R = (Ta − Tb) ÷ (tb − ta) and P = (tb − ta) ÷ (Ta − ta), where T is the shell side and t the tube side, and a is inlet and b is outlet.","explain":"R and P are the two dimensionless temperature ratios behind F. The book's example gives R = 1.83 and P = 0.20 for an oil cooler.","flash":false,"source":"BEE Book 4 Ch 04 p91","order":4211},
{"id":"p4-b04-013","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"What steady-state data does Step A of the field procedure record?","back":"Hot and cold flow rates (W, w), temperatures (T, t) and pressures (P, p) at inlet and outlet for both fluids.","explain":"Readings must be taken at steady state and tabulated. Step B then adds the fluid properties needed for the thermal calculations.","flash":false,"source":"BEE Book 4 Ch 04 p88","order":4212},
{"id":"p4-b04-014","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"Where do the fluid properties for an exchanger test come from?","back":"Density and viscosity come from lab analysis of plant samples at the recorded temperature. Thermal conductivity and specific heat can come from handbooks if not measured.","explain":"Measuring the properties at the recorded temperature keeps the calculation consistent with the test. Handbook values fill the gaps.","flash":false,"source":"BEE Book 4 Ch 04 p89","order":4213},
{"id":"p4-b04-015","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"Why keep a history of an exchanger's U value against time?","back":"A plot of U against date shows the decline due to fouling and allows a rational cleaning schedule.","explain":"Records of U against date make reduced efficiency easy to spot. The plot supports planning when the exchanger should be cleaned.","flash":false,"source":"BEE Book 4 Ch 04 p88","order":4214},
{"id":"p4-b04-016","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"In a test-versus-design comparison, what does a higher cold-side pressure drop with a lower temperature rise suggest?","back":"Increased fouling in the cold-side tubes, which also cuts the effective heat transfer area and lowers U.","explain":"A higher cold-side pressure drop reveals tube fouling, which lowers the cold stream's temperature rise. The book attributes the fall in U to a smaller active heat transfer area.","flash":false,"source":"BEE Book 4 Ch 04 p96","order":4215},
{"id":"p4-b04-017","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"What does non-condensable gas do in a surface condenser?","back":"It raises the condensing pressure and the steam side pressure drop, and it lowers the heat transfer coefficient.","explain":"Non-condensables build up in the condenser and act as a barrier to steam reaching the tubes. The chapter says to look for their source first.","flash":false,"source":"BEE Book 4 Ch 04 p99","order":4216},
{"id":"p4-b04-018","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"What first troubleshooting checks does the chapter give for a condenser with low U?","back":"Check the circuit for tightness, make sure the system is properly vented, and verify that the vacuum source is working.","explain":"These checks target the non-condensable build-up that the chapter identifies as the cause of the lower U.","flash":true,"source":"BEE Book 4 Ch 04 p99","order":4217},
{"id":"p4-b04-019","paper":4,"topic":"Heat Exchanger Effectiveness","kind":"fact","front":"What is Cmin in the effectiveness formula?","back":"The smaller of the two heat capacity rates (W × Cp of each fluid), in kcal/h·°C.","explain":"The fluid with the smaller capacity rate has the largest temperature change, so it sets the maximum possible heat transfer, Qmax = Cmin × ΔTmax.","flash":false,"source":"BEE Book 4 Ch 04 p92","order":4218},
{"id":"p4-b04-020","paper":4,"topic":"Heat Exchanger Effectiveness","kind":"fact","front":"What is the heat capacity ratio of a heat exchanger, and what range does it take?","back":"Cr = Cmin ÷ Cmax, which lies between 0 and 1.","explain":"Cmin is never larger than Cmax, so the ratio cannot exceed 1. It is used with effectiveness in the effectiveness-NTU method.","flash":true,"source":"BEE Book 4 Ch 04 p93","order":4219},
{"id":"p4-b04-021","paper":4,"topic":"Heat Exchanger Effectiveness","kind":"fact","front":"Why does the chapter say effectiveness rather than efficiency for a heat exchanger?","back":"Efficiency is reserved for converting one energy form into another, or for actual against ideal performance. A heat exchanger only moves heat, so the book uses effectiveness.","explain":"The term efficiency is kept for energy conversion or ideal-system comparisons. The first law still applies to the exchanger, through the energy balance behind the definition.","flash":false,"source":"BEE Book 4 Ch 04 p93","order":4220},
{"id":"p4-b04-022","paper":4,"topic":"Heat Exchanger Effectiveness","kind":"fact","front":"If a heat exchanger has effectiveness 0.5, is it only 50% efficient?","back":"No. It means each outlet is halfway to the ideal temperature swap. Two 50 °C and 90 °C air streams would leave at 70 °C each.","explain":"By conservation of energy, heat lost on one side is gained on the other. Effectiveness only measures how well the exchanger swaps temperatures.","flash":false,"source":"BEE Book 4 Ch 04 p93","order":4221},
{"id":"p4-b04-023","paper":4,"topic":"Heat Exchanger Performance","kind":"fact","front":"Which type of heat exchanger is most common in industry?","back":"The shell-and-tube exchanger.","explain":"Shell-and-tube units are used throughout the process and power industries. Their design, construction and performance are core knowledge for an auditor.","flash":true,"source":"BEE Book 4 Ch 04 p87","order":4222},
{"id":"p4-b04-024","paper":4,"topic":"Heat Exchanger Performance","kind":"problem","front":"Example 4.6(a)(i): an oil cooler has hot oil at 719,800 kg/h cooling from 145 °C to 102 °C (Cp 2.847 kJ/kg°C), and cooling water at 881,150 kg/h heating from 25.5 °C to 49 °C (Cp 4.187 kJ/kg°C). What are the hot and cold duties?","back":"Hot side about 24,477 kW; cold side about 24,083 kW, a gap of about 1.6%.","explain":"The two duties should match. The small gap comes from specific heat changing with temperature and some radiation loss from the hot shell, which the book treats as negligible.","flash":false,"source":"BEE Book 4 Ch 04 p94","steps":[{"prompt":"Calculate the hot side duty.","answer":"719,800 × 2.847 × (145 − 102) ÷ 3600 = 24,477 kW","explain":"Hot flow, Cp and temperature drop."},{"prompt":"Calculate the cold side duty.","answer":"881,150 × 4.187 × (49 − 25.5) ÷ 3600 = 24,083 kW","explain":"Cold flow, Cp and temperature rise."},{"prompt":"Compare the two.","answer":"Difference 394 kW, about 1.6%","explain":"A small gap is normal. A large gap points to heat loss or a measurement error."}],"order":4223},
{"id":"p4-b04-025","paper":4,"topic":"Heat Exchanger Performance","kind":"problem","front":"Same oil cooler (hot 145 to 102 °C, cold 25.5 to 49 °C, one shell pass and two tube passes, R = 1.83, P = 0.20): find the counter-current LMTD, the correction factor F and the corrected LMTD.","back":"LMTD about 85.9 °C; F about 0.977; corrected LMTD about 83.9 °C.","explain":"F adjusts the counter-flow LMTD for the mixed flow in a two-pass tube side. Because F is close to 1, the corrected LMTD is only a little below the counter-flow value.","flash":false,"source":"BEE Book 4 Ch 04 p95","steps":[{"prompt":"Find the two end temperature differences.","answer":"145 − 49 = 96 °C; 102 − 25.5 = 76.5 °C","explain":"Counter-flow pairs the hot inlet with the cold outlet, and the hot outlet with the cold inlet."},{"prompt":"Calculate the counter-current LMTD.","answer":"(96 − 76.5) ÷ ln(96 ÷ 76.5) = 19.5 ÷ 0.2271 = 85.9 °C","explain":"The log mean of the two end differences."},{"prompt":"Calculate R and P.","answer":"R = (145 − 102) ÷ (49 − 25.5) = 1.83; P = (49 − 25.5) ÷ (145 − 25.5) = 0.20","explain":"These ratios feed the correction factor formula."},{"prompt":"Apply the correction factor and corrected LMTD.","answer":"F ≈ 0.977 (book value); 0.977 × 85.9 = 83.9 °C","explain":"The corrected LMTD is used in the U calculation."}],"order":4224},
{"id":"p4-b04-026","paper":4,"topic":"Heat Exchanger Performance","kind":"problem","front":"Same oil cooler: duty 24,477.4 kW, heat transfer area 264.55 m² and corrected LMTD 83.9 °C. What is the overall heat transfer coefficient U?","back":"About 1.10 kW/m²·K (1.103 by calculation; the book prints 1.104).","explain":"This test U is compared with the design U of 1.178 kW/m²·K in the book's table. A lower test U points to fouling.","flash":false,"source":"BEE Book 4 Ch 04 p95","steps":[{"prompt":"Write the formula.","answer":"U = Q ÷ (A × corrected LMTD)","explain":"Overall heat transfer coefficient from measured duty."},{"prompt":"Find the denominator.","answer":"264.55 × 83.9 ≈ 22,196","explain":"Area times corrected LMTD."},{"prompt":"Divide.","answer":"24,477.4 ÷ 22,196 ≈ 1.103 kW/m²·K","explain":"The book's 1.104 comes from slightly different rounding."}],"order":4225},
{"id":"p4-b04-027","paper":4,"topic":"Heat Exchanger Effectiveness","kind":"problem","front":"Same oil cooler (duty 24,477.4 kW; oil 719,800 kg/h with Cp 2.847; water 881,150 kg/h with Cp 4.187; hot inlet 145 °C; cold inlet 25.5 °C): find the effectiveness and the heat capacity ratio.","back":"Effectiveness about 0.36; capacity ratio about 0.555 (book prints 0.55).","explain":"Effectiveness is the actual duty divided by the largest duty possible with the smaller capacity rate. Here the oil has the smaller capacity rate, so it sets Cmin.","flash":false,"source":"BEE Book 4 Ch 04 p96","steps":[{"prompt":"Find the capacity rate of each fluid.","answer":"Oil: 719,800 × 2.847 ÷ 3600 = 569.24 kW/°C; water: 881,150 × 4.187 ÷ 3600 = 1024.83 kW/°C","explain":"Capacity rate is mass flow times Cp, converted to kW/°C."},{"prompt":"Identify Cmin and Cmax.","answer":"Cmin = 569.24 (oil); Cmax = 1024.83 (water)","explain":"Cmin is the smaller of the two."},{"prompt":"Find the maximum possible duty.","answer":"ΔTmax = 145 − 25.5 = 119.5 °C; Qmax = 569.24 × 119.5 ≈ 68,027 kW","explain":"ΔTmax is the largest temperature difference between the inlet streams."},{"prompt":"Compute effectiveness and capacity ratio.","answer":"ε = 24,477.4 ÷ 68,027 = 0.36; Cr = 569.24 ÷ 1024.83 = 0.555","explain":"The book prints the capacity ratio as 0.55."}],"order":4226},
{"id":"p4-b04-028","paper":4,"topic":"Heat Exchanger Performance","kind":"problem","front":"A plate heat exchanger with area 41 m² cools hot effluent (85,200 kg/h, Cp 4.187 kJ/kg°C) from 77 °C to 54 °C. Cooling water warms from 49 °C to 57 °C. Take F = 0.9. Find the duty, the LMTD and the U.","back":"Duty about 2,279 kW; LMTD about 10.8 °C; corrected LMTD 9.72 °C; U about 5.72 kW/m²·°C.","explain":"The plate exchanger gives a much higher U than the shell-and-tube units in this chapter, so less area handles the same duty. F = 0.9 is given in the problem rather than calculated.","flash":false,"source":"BEE Book 4 Ch 04 p97","steps":[{"prompt":"Calculate the heat duty.","answer":"85,200 × 4.187 × (77 − 54) ÷ 3600 = 2,279 kW","explain":"Hot flow, Cp and temperature drop."},{"prompt":"Calculate the counter-current LMTD.","answer":"[(77 − 57) − (54 − 49)] ÷ ln[(77 − 57) ÷ (54 − 49)] = 15 ÷ 1.386 = 10.8 °C","explain":"End differences are hot inlet minus cold outlet, and hot outlet minus cold inlet."},{"prompt":"Apply the correction factor.","answer":"0.9 × 10.8 = 9.72 °C","explain":"Corrected LMTD for the plate pattern."},{"prompt":"Calculate U.","answer":"2,279 ÷ (41 × 9.72) = 5.72 kW/m²·°C","explain":"U = Q ÷ (A × corrected LMTD)."}],"order":4227},
{"id":"p4-b04-029","paper":4,"topic":"Heat Exchanger Performance","kind":"problem","front":"A counter-flow double-pipe exchanger has heat transfer area 18.5 m² and transfers 1025.85 kW. Using the book's LMTD of 85.2 °C, what is the overall heat transfer coefficient U?","back":"About 0.651 kW/m²·K.","explain":"The hot stream runs in the inner pipe, counter to the cold stream in the outer pipe. The LMTD of 85.2 °C is taken as the book prints it.","flash":false,"source":"BEE Book 4 Ch 04 p97","steps":[{"prompt":"Write the formula.","answer":"U = Q ÷ (A × LMTD)","explain":"Overall heat transfer coefficient from duty, area and LMTD."},{"prompt":"Find the denominator.","answer":"18.5 × 85.2 = 1,576.2","explain":"Area times LMTD."},{"prompt":"Divide.","answer":"1025.85 ÷ 1576.2 = 0.651 kW/m²·K","explain":"The result is the overall U for this pipe."}],"order":4228},
{"id":"p4-b04-030","paper":4,"topic":"Heat Exchanger Performance","kind":"problem","front":"A surface condenser condenses 939,888 kg/h of exhaust steam with latent heat 2210 kJ/kg. Cooling water flows at 55,584,000 kg/h and warms from 18 °C to 27 °C (Cp 4.187 kJ/kg°C). What are the steam side and water side duties?","back":"Steam side about 576,990 kW; water side about 581,826 kW.","explain":"The steam side duty is latent only, since the steam condenses at a constant 34.9 °C. The small difference from the water side is within normal property and measurement variation.","flash":false,"source":"BEE Book 4 Ch 04 p98","steps":[{"prompt":"Convert the steam flow to kg/s.","answer":"939,888 ÷ 3600 = 261.08 kg/s","explain":"The chapter's duty formula uses kg/s here."},{"prompt":"Calculate the steam side duty.","answer":"261.08 × 2210 = 576,990 kW","explain":"Condensing duty is mass flow times latent heat."},{"prompt":"Calculate the water side duty.","answer":"15,440 × 4.187 × (27 − 18) = 581,826 kW","explain":"The water flow is 55,584,000 ÷ 3600 = 15,440 kg/s; its temperature rise sets the duty."}],"order":4229},
{"id":"p4-b04-031","paper":4,"topic":"Heat Exchanger Performance","kind":"problem","front":"Same surface condenser: duty 576,990 kW, area 30,151 m², steam condensing at 34.9 °C, water 18 to 27 °C, F = 1.0. Find the LMTD and U.","back":"LMTD about 11.8 °C; U about 1.62 kW/m²·K (book prints 1.622).","explain":"Only the condensing part is used for the LMTD, since the steam stays at 34.9 °C throughout condensation. The book's design U is 2.37 kW/m²·K, so the test figure shows the condenser has degraded.","flash":false,"source":"BEE Book 4 Ch 04 p99","steps":[{"prompt":"Find the temperature differences.","answer":"34.9 − 18 = 16.9 °C; 34.9 − 27 = 7.9 °C","explain":"Steam temperature is constant during condensation."},{"prompt":"Calculate the LMTD.","answer":"(16.9 − 7.9) ÷ ln(16.9 ÷ 7.9) = 9 ÷ 0.7608 = 11.8 °C","explain":"Logarithmic mean of the two differences."},{"prompt":"Apply the correction factor.","answer":"F = 1.0, so the corrected LMTD is 11.8 °C","explain":"A single-pass condenser needs no correction."},{"prompt":"Calculate U.","answer":"576,990 ÷ (30,151 × 11.8) = 1.622 kW/m²·K","explain":"Test U, to compare with the design value."}],"order":4230},
{"id":"p4-b04-032","paper":4,"topic":"Heat Exchanger Performance","kind":"problem","front":"Solved example: hot water at 12 kg/min cools from 72 °C to 52 °C, cold water at 30 kg/min enters at 27 °C (Cp 4.179 kJ/kg·K). U = 800 W/m²·K, fouling neglected. What area is needed for parallel flow?","back":"About 0.73 m² (book prints 0.72 m²).","explain":"Parallel flow gives a smaller LMTD than counter-flow for the same end temperatures, so it needs more area. Compare with the counter-flow answer on the next card.","flash":false,"source":"BEE Book 4 Ch 04 p100","steps":[{"prompt":"Calculate the duty.","answer":"(12 ÷ 60) × 4.179 × 1000 × (72 − 52) = 16,716 W","explain":"kg/s times J/kg·K times K gives W."},{"prompt":"Find the cold outlet temperature.","answer":"27 + 16,716 ÷ (4.179 × 1000 × 30 ÷ 60) = 27 + 8 = 35 °C","explain":"Cold water picks up the same heat."},{"prompt":"Find the parallel-flow end differences.","answer":"72 − 27 = 45 °C; 52 − 35 = 17 °C","explain":"In parallel flow the hot inlet pairs with the cold inlet."},{"prompt":"Calculate the LMTD.","answer":"(45 − 17) ÷ ln(45 ÷ 17) = 28.76 °C","explain":"Logarithmic mean of the end differences."},{"prompt":"Calculate the area.","answer":"16,716 ÷ (800 × 28.76) = 0.73 m²","explain":"The book prints 0.72 m²; the rounding differs."}],"order":4231},
{"id":"p4-b04-033","paper":4,"topic":"Heat Exchanger Performance","kind":"problem","front":"Same water data (hot 72 to 52 °C, cold 27 to 35 °C, duty 16,716 W, U = 800 W/m²·K): find the heat transfer area for counter-flow.","back":"About 0.68 m² (book prints 0.684 m²).","explain":"Counter-flow keeps the end differences more even, giving a larger LMTD (30.6 °C) and so less area for the same duty.","flash":false,"source":"BEE Book 4 Ch 04 p100","steps":[{"prompt":"Find the counter-flow end differences.","answer":"72 − 35 = 37 °C; 52 − 27 = 25 °C","explain":"In counter-flow the hot inlet pairs with the cold outlet."},{"prompt":"Calculate the LMTD.","answer":"(37 − 25) ÷ ln(37 ÷ 25) = 12 ÷ 0.392 = 30.6 °C","explain":"Logarithmic mean of the end differences."},{"prompt":"Calculate the area.","answer":"16,716 ÷ (800 × 30.6) = 0.68 m²","explain":"The book prints 0.684 m², using a slightly more precise LMTD."}],"order":4232}
]$cards$::jsonb);
